   319      if (xcf_io.readRawData(tag, sizeof(tag)) != sizeof(tag)) {
   320  //             qDebug() << "XCF: read failure on header tag";
   321          return false;
   322      }
   323      if (qstrncmp(tag, "gimp xcf", 8) != 0) {
   324  //             qDebug() << "XCF: read called on non-XCF file";
   325          return false;
   326      }
   327
   328      xcf_io >> xcf_image.width >> xcf_image.height >> xcf_image.type;
   329
   330  //  qDebug() << tag << " " << xcf_image.width << " " << xcf_image.height << " " <<  xcf_image.type;
   331      if (!loadImageProperties(xcf_io, xcf_image)) {
   332          return false;
   333      }
