   335      // The layers appear to be stored in top-to-bottom order. This is
   336      // the reverse of how a merged image must be computed. So, the layer
   337      // offsets are pushed onto a LIFO stack (thus, we don't have to load
   338      // all the data of all layers before beginning to construct the
   339      // merged image).
   340
   341      QStack<qint32> layer_offsets;
   342
   343      while (true) {
   344          qint32 layer_offset;
   345
   346          xcf_io >> layer_offset;
   347
   348          if (layer_offset == 0) {
   349              break;
   350          }
   351
   352          layer_offsets.push(layer_offset);
   353      }
   354
   355      xcf_image.num_layers = layer_offsets.size();
