  1513      } else if (pe) {
  1514          x1 = qMax(r.x(), pe->deviceRect.x());
  1515          x2 = qMin(r.x() + r.width(), pe->deviceRect.x() + pe->deviceRect.width());
  1516          y1 = qMax(r.y(), pe->deviceRect.y());
